fn binding(m:&email::Mailbox)->Value{json!({"endpoint":m.endpoint,"account":m.account,"mailbox":m.mailbox,"credential":m.credential})}
fn addresses(v:&Value)->String{if let Some(s)=v.as_str(){s.into()}else{v.as_array().into_iter().flatten().filter_map(|r|r["email"].as_str()).collect::<Vec<_>>().join(", ")}}
pub fn controller(input:Value,c:&Config)->Value{controller_with_workflows(input,c,&Workflows::default())}
