fn folder_request(m:&email::Mailbox)->Value{call(m,json!([["Mailbox/get",{"accountId":m.account,"ids":null,"properties":["id","name","role"]},"folders"]]),"mail.folders.loaded")}
fn open_connection(s:&mut Value,c:&Config,w:&Workflows)->Value{for key in["body","download","selected_header","draft_child","identity"]{s[key]=Value::Null;}for key in["folders","drafts","identities"]{s[key]=json!([]);}for key in["api_url","server_account","selected_mailbox","drafts_id","sent_id","server_accounts","upload_url","download_url","read_only","can_submit","server_label","selected_mailbox_label"]{s.as_object_mut().unwrap().remove(key);}if !w.session_url.is_empty(){s["route"]=json!("connecting");s["status"]=json!("Discovering the configured provider's mail accounts");email_session::request(w.session_url,s["active"]["account"].as_str().unwrap_or(""),"mail.session")}else{s["route"]=json!("headers");let _=c;email::load("mail.loaded")}}

fn file_row<'a>(s:&'a Value,index:&str)->Option<&'a Value>{index.parse::<usize>().ok().and_then(|i|s["files"].as_array()?.get(i))}

fn file_page(after:&str)->Value{let mut request=blobs::list(after,"mail.files.loaded");request["args"]["limit"]=json!(20);request}
